add(s,'d','Cardinality can be 1 or Many and the symbol is placed on the outside ends of the relationship line, closest to the entity. Modality can be 1 or 0 and the symbol is placed on the inside, next to cardinality symbol.','کارڈینالٹی ۱ یا کئی ہو سکتی ہے اور علامت ریلیشن شپ لائن کے بیرونی سروں پر، انٹیٹی کے قریب ترین، رکھی جاتی ہے۔ موڈیلٹی ۱ یا ۰ ہو سکتی ہے اور علامت اندر کی طرف، کارڈینالٹی علامت کے ساتھ، رکھی جاتی ہے۔','کارډینالټي ۱ یا ډیر کېدای شي او سمبول د اړیکې د کرښې په بهرنیو سرونو کې، وجود ته تر ټولو نژدې، ایښودل کېږي. موډالټي ۱ یا ۰ کېدای شي او سمبول په دننه کې، د کارډینالټي سمبول تر څنګ، ایښودل کېږي.')
add(s,'e','For a cardinality of 1 a straight line is drawn. For a cardinality of Many a foot with three toes is drawn. For modality of 1 a straight line is drawn. For a modality of 0 a circle is drawn.','کارڈینالٹی ۱ کے لیے سیدھی لکیر کھینچی جاتی ہے۔ کارڈینالٹی کئی کے لیے تین انگلیوں والا پاؤں بنایا جاتا ہے۔ موڈیلٹی ۱ کے لیے سیدھی لکیر کھینچی جاتی ہے۔ موڈیلٹی ۰ کے لیے دائرہ بنایا جاتا ہے۔','د کارډینالټي ۱ لپاره سیده کرښه ایستل کېږي. د کارډینالټي ډیر لپاره درې ګوتو لرونکی پښه ایستل کېږي. د موډالټي ۱ لپاره سیده کرښه ایستل کېږي. د موډالټي ۰ لپاره حلقه ایستل کېږي.')
def card():
    def row(y,label,left):
        b=f'<line x1="60" y1="{y}" x2="360" y2="{y}" stroke="#111" stroke-width="1.5"/>'+T(210,y+22,label,12,'middle',700)
        if left=='zm': b+=f'<polyline points="10,{y-10} 40,{y} 10,{y+10}" fill="none" stroke="#111" stroke-width="1.5"/><circle cx="48" cy="{y}" r="5" fill="#fff" stroke="#111"/>'
        elif left=='om': b+=f'<polyline points="10,{y-10} 40,{y} 10,{y+10}" fill="none" stroke="#111" stroke-width="1.5"/><line x1="48" y1="{y-9}" x2="48" y2="{y+9}" stroke="#111" stroke-width="1.5"/>'
        elif left=='oo': b+=f'<line x1="30" y1="{y-9}" x2="30" y2="{y+9}" stroke="#111" stroke-width="1.5"/><line x1="40" y1="{y-9}" x2="40" y2="{y+9}" stroke="#111" stroke-width="1.5"/>'
        else: b+=f'<line x1="30" y1="{y-9}" x2="30" y2="{y+9}" stroke="#111" stroke-width="1.5"/><circle cx="46" cy="{y}" r="5" fill="#fff" stroke="#111"/>'
        return b
    b=row(20,'zero or more','zm')+row(75,'1 or more','om')+row(130,'1 and only1','oo')+row(185,'zero or1','z1')
    return svg(380,225,'Cardinality and modality symbols: zero or more, one or more, one and only one, zero or one',b)
